if not error_message:
    try:
        insert_count = spark.sql(f"SELECT COUNT(*) FROM {view_name}").collect()[0][0]
        print(f"View {view_name} row count: {insert_count}")
        end_exec_time = datetime.now()

    except Exception as e:
        error_message = f"Error counting rows in {view_name} : {str(e)[:800]}"
        end_exec_time = datetime.now()
